initial_condition:
with {
    the SUT being in the "initial state" and
    the SUT containing an initial Entity ${entity} 
        with an id set to ${entityId} 
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Batch Delete Entities with Response Status Code set to 207     and
        ${response.json()} with Response body containing batch operation result set to '${response1}'     and
        Query Entities with Response body is empty
}
